import {chinaDate} from './cloud-contract.mjs';
import {signedCostMoney} from './cost-sources-contract.mjs';
import {hasSensitive} from './admin-permissions.mjs';
export function createCashViews({api,h,showPanel,getUser,writable,notify,localTime}){
 let current={month:chinaDate().slice(0,7),direction:'all',status:'active',q:'',offset:0};
 const amount=v=>h(signedCostMoney(String(v))),maintain=()=>writable&&hasSensitive(getUser(),'finance');
 const head=t=>`<div class="dialog-header"><h2>${h(t)}</h2><button class="icon-button" data-cash-close aria-label="关闭资金核对">×</button></div>`;
 const sourceLink=s=>s.kind==='income'?`<button class="text-button" data-income-history="${h(s.storeId)}" data-month="${h(s.month)}">查看原收入确认</button>`:`<button class="text-button" data-overview-expense="${h(s.expenseId)}">查看原支出</button>`;
 async function list(params=current){current={...params};const q={...current};await showPanel('实际到账与付款',async signal=>{const d=await api.cashMovements(q,signal),s=d.summary;
  return head('实际到账与付款')+'<p>按实际到账／付款日期列示已登记资金，报销付款沿用原记录。此处不新增经营收入或费用，也不代表完整银行账或账户余额。</p>'+`<form data-cash-filter class="module-toolbar"><label>资金月份<input name="month" type="month" min="1900-01" max="2199-12" value="${h(q.month)}" required></label><label>方向<select name="direction">${[['all','全部'],['in','到账'],['out','付款']].map(([v,l])=>`<option value="${v}" ${q.direction===v?'selected':''}>${l}</option>`).join('')}</select></label><label>状态<select name="status">${[['active','有效'],['void','已作废'],['all','全部']].map(([v,l])=>`<option value="${v}" ${q.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>查找<input name="q" value="${h(q.q)}" maxlength="100" placeholder="事项、渠道或流水编号"></label><button class="secondary">筛选</button></form>
   <section class="summary-strip"><div><b>${amount(s.inCents)}</b><span>有效到账</span></div><div><b>${amount(s.outCents)}</b><span>有效付款（含报销）</span></div><div><b>${amount(s.reimbursementCents)}</b><span>其中原报销付款</span></div><div><b>${amount(s.unmatchedCents)}</b><span>暂未对应原来源</span></div></section><p class="muted">以上合计覆盖当前筛选的全部记录，作废金额不计入；暂未对应金额是双向金额合计，不是净现金余额。</p><div class="action-row">${maintain()?'<button class="primary" data-cash-edit="" data-direction="in">登记实际到账</button><button class="secondary" data-cash-edit="" data-direction="out">登记公司付款</button>':''}<button class="secondary" data-cash-sources="income" data-month="${h(q.month)}">按原收入核对到账</button><button class="secondary" data-cash-sources="expense" data-month="${h(q.month)}">按原支出核对付款</button><a href="#settlements" class="text-button" data-cash-close>进入原结算与报销</a></div>`+
   d.rows.map(r=>`<button class="account-row" ${r.origin==='manual'?'data-cash-detail':'data-cash-payment'}="${h(r.id)}"><span><b>${h(r.description)}${r.status==='void'?' · 已作废':''}</b><small>${h(r.paidDate)} · ${r.origin==='reimbursement'?'原报销付款（沿用记录）':h(r.accountLabel)+' · '+h(r.sourceReference)}${r.origin==='manual'?' · 暂未对应 '+amount(r.unmatchedCents):''}</small></span><span>${r.direction==='in'?'到账':'付款'} ${amount(r.amountCents)} ›</span></button>`).join('')+(!d.rows.length?'<p class="muted">暂无符合筛选的资金记录。</p>':'')+`<div class="pager"><button class="secondary" data-cash-page="${Math.max(0,q.offset-50)}" ${q.offset===0?'disabled':''}>上一页</button><span>${d.total} 条记录</span><button class="secondary" data-cash-page="${q.offset+50}" ${q.offset+50>=d.total?'disabled':''}>下一页</button></div>`;
 });}
 async function detail(id,offset=0){await showPanel('资金记录与来源对应',async signal=>{const d=await api.cashMovement(id,offset,signal),r=d.record;
  return head(r.description)+`<button class="text-button" data-cash-list>返回资金核对</button><p>${h(r.paidDate)} · ${r.direction==='in'?'到账':'付款'} ${amount(r.amountCents)} · ${r.status==='void'?'已作废':'有效'}</p><p>${h(r.accountLabel)} · ${h(r.sourceReference)}</p><p>本笔暂未对应 ${amount(d.unmatchedCents)}。${r.status==='void'?'本笔已移出有效资金与累计对应额。':''}</p>${maintain()&&r.status==='active'?`<button class="secondary" data-cash-edit="${h(id)}">修正金额、日期或来源对应</button><button class="text-button" data-cash-void="${h(id)}">作废本笔</button>`:''}<h3>原来源对应</h3>`+
   d.matches.map(m=>`<article class="observation"><b>${h(m.line.snapshot.label)} · 本次对应 ${amount(m.line.amountCents)}</b><p>来源月份 ${h(m.line.snapshot.month)} · 原来源第 ${m.line.snapshot.version} 版${m.current?'，当前第 '+m.current.version+' 版':'，当前不可见'}</p><p>该来源跨月累计有效对应 ${amount(m.cashCents)} · ${m.differenceCents===null?'原金额待核对':(m.line.kind==='income'?'收入与到账对应差额':'支出与付款对应差额')+' '+amount(m.differenceCents)}</p>${m.sourceChanged||m.overmatched?'<p class="save-error">原来源已有变化、失效或累计付款超过原支出，请重新核对本笔对应。</p>':''}${sourceLink(m.line.snapshot)}</article>`).join('')+(!d.matches.length?'<p class="muted">尚未对应原来源。</p>':'')+'<p class="muted">收入与到账差额只供核对，不自动视为未收款、退款、手续费或新收入。所有对应均不改经营利润、支出或报销余额。</p><h3>版本历史</h3>'+d.history.rows.map(v=>`<article class="observation"><b>第 ${v.version} 版 · ${h(v.paidDate)} · ${amount(v.amountCents)} · ${v.status==='void'?'已作废':'有效'}</b><p>${h(v.description)} · ${v.lines.length} 项对应</p>${v.lines.map(l=>`<p>${h(l.snapshot.label)} · ${amount(l.amountCents)} · 原来源第 ${l.snapshot.version} 版</p>`).join('')}<p class="preserve-text">${h(v.reason)}</p><small>${h(v.actor)} · ${h(localTime(v.createdAt))}</small></article>`).join('')+`<div class="pager"><button class="secondary" data-cash-detail="${h(id)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${d.history.total} 条版本</span><button class="secondary" data-cash-detail="${h(id)}" data-offset="${offset+50}" ${offset+50>=d.history.total?'disabled':''}>下一页</button></div>`;
 });}
 async function sources(kind='income',month=current.month,offset=0,q=''){await showPanel('原来源与实际资金对应',async signal=>{const d=await api.cashSources({kind,month,offset,q},signal);
  return head(kind==='income'?'按原收入核对到账':'按原支出核对付款')+`<button class="text-button" data-cash-list>返回实际到账与付款</button><form data-cash-sources-filter class="module-toolbar"><input name="kind" type="hidden" value="${h(kind)}"><label>原来源月份<input name="month" type="month" value="${h(month)}" min="1900-01" max="2199-12" required></label><label>查找<input name="q" value="${h(q)}" maxlength="100"></label><button class="secondary">筛选</button></form><p>按原${kind==='income'?'收入确认':'支出发生'}月份列示，对应金额累计全部资金月份，支持跨月。${kind==='income'?'差额不自动表示未到账，不推断手续费或退款。':'只列公司支付支出；个人垫付沿用原结算与报销。'}</p>`+
   d.rows.map(r=>`<article class="observation"><b>${h(r.label)} · ${h(r.month)}</b><p>原金额 ${amount(r.amountCents)} · 累计有效对应 ${amount(r.cashCents)} · 差额 ${amount(r.differenceCents)}</p>${sourceLink(r)}</article>`).join('')+(!d.rows.length?'<p class="muted">暂无匹配的有效原来源。</p>':'')+`<div class="pager"><button class="secondary" data-cash-sources="${h(kind)}" data-month="${h(month)}" data-q="${h(q)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${d.total} 条来源</span><button class="secondary" data-cash-sources="${h(kind)}" data-month="${h(month)}" data-q="${h(q)}" data-offset="${offset+50}" ${offset+50>=d.total?'disabled':''}>下一页</button></div>`;
 });}
 async function payment(id){await showPanel('原报销付款',async signal=>{const d=await api.finance(signal),p=d.payments.find(p=>p.id===id);if(!p)throw Error('原报销付款暂不可见。');return head('原报销付款')+`<button class="text-button" data-cash-list>返回资金核对</button><p>${h(p.paidDate)} · ${h(p.payerName)} · ${amount(p.amountCents)}</p><p class="preserve-text">${h(p.note)}</p><p>直接沿用原报销付款，不重复创建资金记录、费用或报销。原记录未填写付款账户，不在此推测。</p><a href="#settlements" class="text-button" data-cash-close>查看原结算与报销</a>`;});}
 document.addEventListener('click',e=>{if(e.target.closest('[data-cash-close]'))document.querySelector('#cloud-detail').close();const l=e.target.closest('[data-cash-list]'),p=e.target.closest('[data-cash-page]'),r=e.target.closest('[data-cash-detail]'),s=e.target.closest('[data-cash-sources]'),pay=e.target.closest('[data-cash-payment]');if(l)list().catch(e=>notify(e.message));if(p)list({...current,offset:Number(p.dataset.cashPage)}).catch(e=>notify(e.message));if(r)detail(r.dataset.cashDetail,Number(r.dataset.offset||0)).catch(e=>notify(e.message));if(s)sources(s.dataset.cashSources,s.dataset.month||current.month,Number(s.dataset.offset||0),s.dataset.q||'').catch(e=>notify(e.message));if(pay)payment(pay.dataset.cashPayment).catch(e=>notify(e.message));});
 document.addEventListener('submit',e=>{if(e.target.matches('[data-cash-filter]')){e.preventDefault();const f=new FormData(e.target);list({month:f.get('month'),direction:f.get('direction'),status:f.get('status'),q:f.get('q').trim(),offset:0}).catch(e=>notify(e.message));}if(e.target.matches('[data-cash-sources-filter]')){e.preventDefault();const f=new FormData(e.target);sources(f.get('kind'),f.get('month'),0,f.get('q').trim()).catch(e=>notify(e.message));}});
 return {list,detail,sources};
}
